{
  "name": "pstack",
  "private": true,
  "version": "0.9.88",
  "description": "If you want to go fast, go deep first. pstack helps you write less, but higher quality code. rigorous agent workflows you can parallelize with confidence. Pi package of the Claude Code plugin; skills are shared, tool names resolve via skills/poteto-mode/references/pi-tools.md. Original pstack by Lauren Tan (poteto).",
  "author": {
    "name": "Michael Denyer",
    "url": "https://github.com/michael-denyer"
  },
  "homepage": "https://github.com/michael-denyer/pstack-claude",
  "repository": "https://github.com/michael-denyer/pstack-claude",
  "license": "MIT",
  "keywords": [
    "pi-package",
    "pstack",
    "poteto-mode",
    "workflow",
    "principles",
    "agent-style",
    "subagents",
    "unslop",
    "claude-code",
    "skills",
    "tdd",
    "code-review",
    "parallel-agents",
    "codex",
    "opencode",
    "gemini-cli",
    "prime-agent"
  ],
  "pi": {
    "skills": [
      "./plugins/pstack/skills"
    ],
    "extensions": [
      "./plugins/pstack/pi/index.ts"
    ]
  },
  "peerDependencies": {
    "@earendil-works/pi-coding-agent": "*",
    "typebox": "*"
  },
  "peerDependenciesMeta": {
    "@earendil-works/pi-coding-agent": {
      "optional": true
    }
  }
}

{
  "name": "superdesign-official",
  "displayName": "Superdesign Dev",
  "description": "The 1st Design Agent lives inside your IDE",
  "version": "0.0.14",
  "publisher": "SuperdesignDev",
  "icon": "icon.png",
  "repository": {
    "type": "git",
    "url": "https://github.com/superdesigndev/superdesign"
  },
  "engines": {
    "vscode": "^1.90.0"
  },
  "categories": [
    "AI",
    "Other"
  ],
  "keywords": [
    "design",
    "ui",
    "mockup",
    "wireframe",
    "component",
    "ai",
    "agent",
    "figma",
    "prototype",
    "layout",
    "frontend",
    "react",
    "html",
    "css",
    "claude",
    "anthropic",
    "generator",
    "automation"
  ],
  "activationEvents": [
    "onCommand:superdesign.helloWorld",
    "onView:superdesign.chatView"
  ],
  "main": "./dist/extension.js",
  "contributes": {
    "commands": [
      {
        "command": "superdesign.helloWorld",
        "title": "Hello World",
        "category": "Superdesign"
      },
      {
        "command": "superdesign.configureApiKey",
        "title": "Configure Anthropic API Key",
        "category": "Superdesign"
      },
      {
        "command": "superdesign.configureOpenAIApiKey",
        "title": "Configure OpenAI API Key",
        "category": "Superdesign"
      },
      {
        "command": "superdesign.configureOpenAIUrl",
        "title": "Configure OpenAI url",
        "category": "Superdesign"
      },
      {
        "command": "superdesign.configureOpenRouterApiKey",
        "title": "Configure OpenRouter API Key",
        "category": "Superdesign"
      },
      {
        "command": "superdesign.showChatSidebar",
        "title": "Show Chat Sidebar",
        "category": "Superdesign"
      },
      {
        "command": "superdesign.openCanvas",
        "title": "Open Canvas View",
        "category": "Superdesign",
        "icon": "$(window)"
      },
      {
        "command": "superdesign.clearChat",
        "title": "Clear Chat",
        "category": "Superdesign",
        "icon": "$(clear-all)"
      },
      {
        "command": "superdesign.resetWelcome",
        "title": "Reset Welcome Screen",
        "category": "Superdesign"
      },
      {
        "command": "superdesign.initializeProject",
        "title": "Initialize Superdesign",
        "category": "Superdesign"
      },
      {
        "command": "superdesign.openSettings",
        "title": "Open Settings",
        "category": "Superdesign",
        "icon": "$(settings-gear)"
      }
    ],
    "menus": {
      "view/title": [
        {
          "command": "superdesign.openCanvas",
          "when": "view == superdesign.chatView",
          "group": "navigation"
        },
        {
          "command": "superdesign.openSettings",
          "when": "view == superdesign.chatView",
          "group": "navigation"
        },
        {
          "command": "superdesign.clearChat",
          "when": "view == superdesign.chatView",
          "group": "navigation"
        }
      ]
    },
    "views": {
      "superdesign-sidebar": [
        {
          "type": "webview",
          "id": "superdesign.chatView",
          "name": "SUPER DESIGN",
          "when": "true"
        }
      ]
    },
    "viewsContainers": {
      "activitybar": [
        {
          "id": "superdesign-sidebar",
          "title": "Superdesign",
          "icon": "icon.svg"
        }
      ]
    },
    "configuration": {
      "title": "Superdesign",
      "properties": {
        "superdesign.llmProvider": {
          "type": "string",
          "enum": [
            "claude-api",
            "claude-code"
          ],
          "enumDescriptions": [
            "Use Anthropic API key to communicate with Claude via SDK",
            "Use local claude binary for enhanced code execution capabilities"
          ],
          "default": "claude-api",
          "description": "Choose the LLM provider to use for AI interactions",
          "scope": "application"
        },
        "superdesign.anthropicApiKey": {
          "type": "string",
          "description": "Anthropic API key for Claude Code integration (required for claude-api provider)",
          "scope": "application"
        },
        "superdesign.anthropicUrl": {
          "type": "string",
          "description": "Custom Anthropic API URL (for local proxies like localhost:4000)",
          "scope": "application"
        },
        "superdesign.claudeCodePath": {
          "type": "string",
          "description": "Path to claude binary (defaults to 'claude' for npm install, use 'claude-code' if installed via shell script)",
          "scope": "application"
        },
        "superdesign.claudeCodeModelId": {
          "type": "string",
          "enum": [
            "claude-sonnet-4-20250514",
            "claude-3-5-sonnet-20241022",
            "claude-3-5-haiku-20241022",
            "claude-3-opus-20240229"
          ],
          "default": "claude-sonnet-4-20250514",
          "description": "Model
